      "nounCount": 1,
      "vocabId": "w:回:hui2",
      "syllabus": {"vocab":[{"no":81,"level":"HSK1","pos":"动、（量）","measureLevel":"HSK3"}],"grammar":[{"no":162,"level":"HSK3","item":"动量词"}]},
