      "usage": "Zählt Mahlzeiten; gehobener als 顿 (dùn) und typisch für feste Wendungen, Hinweise und Schriftsprache, etwa 一日三餐 (yí rì sān cān) oder 每餐 (měi cān).",
      "questionWord": "几餐",
